              "type": "line",
              "speaker": "mango",
              "speakerLabel": "Mango",
              "text": "The Lost Things Office. Nib runs it. Everything has a tag and a shelf.",
              "html": "The Lost Things Office. Nib runs it. Everything has a tag and a shelf.",
