              "id": "ch01.s02.b025",
              "type": "line",
              "speaker": "mango",
              "speakerLabel": "Mango",
              "text": "Come on, come on! Or we can visit the singers. Either way, we find your thing!",
              "html": "Come on, come on! Or we can visit the singers. Either way, we find your thing!",
