              "type": "line",
              "speaker": "mango",
              "speakerLabel": "Mango",
              "text": "That is Nib! He runs the Lost Things Office. He sings here on his lunch break.",
              "html": "That is Nib! He runs the Lost Things Office. He sings here on his lunch break.",
