              "id": "ch06.s01.b017",
              "type": "line",
              "speaker": "grumble",
              "speakerLabel": "Grumble",
              "text": "I will keep it forever. On the tallest pile. Where everyone can see.",
              "html": "I will keep it forever. On the tallest pile. Where everyone can see.",
