              "type": "line",
              "speaker": "grumble",
              "speakerLabel": "Grumble",
              "text": "Mmm. A good trade. The best kind. Now, small visitor, how will you get home?",
              "html": "Mmm. A good trade. The best kind. Now, small visitor, how will you get home?",
