        "ch03.s01.b053": "Hmm. Zlatni gumb svjetluca, ali je malen. Lokve bi mogle imati nešto bolje.",
        "ch03.s01.b054": "Zmajevi pjevači tiho pjevuše. Povjetarac koji miriše na slatkiše nježno prođe Petri kroz kosu.",
        "ch03.s01.b055": "Petra čvrsto drži zlatni gumb. Pred njom je velik izbor.",
        "ch04.s01.b001": "Petra hoda stazom. Kamenje svjetluca pod njezinim crvenim čizmama.",
        "ch04.s01.b002": "Špilja pred njom sjaji poput svjetiljke. Iz nje se kotrlja glasno, duboko hrkanje.",
