        "ch04.s01.b017": "Zdravo. Ja sam Petra. Ta plava duda je moja. Pa, moja je od mog malog brata.",
        "ch04.s01.b018": "Duda. Mmm. Sviđa mi se. Okrugla je i plava i sjajna.",
