        "ch04.s01.b039": "U njezinu džepu leži mali zlatni gumb od Niba. Malen je i topao i donosi sreću. Mango još ima i svoj sjajni gumb.",
        "ch04.s01.b041": "Ja imam svoj gumb! Onaj koji sam dobio u zamjenu za dudu. Baš je sjajan! Baš okrugao!",
